def isRationalEqual(s: str, t: str) -> bool:
    from fractions import Fraction
    def parse(val):
        if '(' not in val:
            return Fraction(val)
        dot = val.find('.')
        left_paren = val.find('(')
        integer_part = val[:dot] if dot != -1 else val[:left_paren]
        non_repeat = val[dot + 1:left_paren] if dot != -1 else ""
        repeat = val[left_paren + 1:-1]
        res = Fraction(int(integer_part) if integer_part else 0, 1)
        if non_repeat:
            res += Fraction(int(non_repeat), 10 ** len(non_repeat))
        repeat_frac = Fraction(int(repeat), (10 ** len(repeat) - 1) * (10 ** len(non_repeat)))
        res += repeat_frac
        return res
    return parse(s) == parse(t)

